head.script:
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#input1').simulate('key-sequence', {
        sequence: 'ㅠㅠㅊㄹ호아ㅓㅣㅓㅇ노'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. IE에서 샘플파일 실행 후 input1의 inputbox에 한글을 입력한다.
    //1. After executing the sample file in IE, input Hangul in the input box of input1.
    //Verify step 1. Hangul is entered normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').val() == 'ㅠㅠㅊㄹ호아ㅓㅣㅓㅇ노'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 05-May-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
